package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaKnDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("ನನ್ನ ದುಷ್ಕೃತ್ಯಗಳಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಮಾಡಿದ ದುಷ್ಕೃತ್ಯಗಳಿಂದ ಮತ್ತು ಮಾಡದ ದುಷ್ಕೃತ್ಯಗಳಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಆಯಿಶಾ (ರ.) ಪ್ರಕಾರ, ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರ ಒಂದು ದುಆ.", "ಏನು ಮಾಡಲಾಗಿದೆ ಮತ್ತು ಏನು ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ ಎಂಬುದರ ಪರಿಣಾಮಗಳಿಂದ ರಕ್ಷಣೆ."),
        "dua_jahdil_bala" to DuaText("ತೀವ್ರ ವಿಚಾರಣೆಗಳಿಂದ ನಿರಾಶ್ರಿತರಾದವರು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನಲ್ಲಿ ಕಠಿಣವಾದ ವಿಚಾರಣೆಯಿಂದ, ದುಃಖದಿಂದ, ಕೆಟ್ಟ ಆದೇಶದಿಂದ ಮತ್ತು ಶತ್ರುಗಳ ಹೊಗಳಿಕೆಯಿಂದ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ತೀವ್ರತರವಾದ ಪರೀಕ್ಷೆಗಳು ಮತ್ತು ಶತ್ರುಗಳ ಉಲ್ಲಾಸದಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಈ ನಾಲ್ಕು ವಿಷಯಗಳಿಂದ ಆಶ್ರಯ ಪಡೆದರು."),
        "dua_fitnat_ghina_faqr" to DuaText("ಸಂಪತ್ತು ಮತ್ತು ಬಡತನದ ಪರೀಕ್ಷೆಗಳ ಆಶ್ರಯ", "ಓ ಅಲ್ಲಾಹನೇ, ಸೋಮಾರಿತನ ಮತ್ತು ವೃದ್ಧಾಪ್ಯದಿಂದ, ಪಾಪ ಮತ್ತು ಸಾಲದಿಂದ, ಸಮಾಧಿಯ ವಿಚಾರಣೆ ಮತ್ತು ಶಿಕ್ಷೆಯಿಂದ, ಬೆಂಕಿಯ ವಿಚಾರಣೆ ಮತ್ತು ಶಿಕ್ಷೆಯಿಂದ, ಸಂಪತ್ತಿನ ವಿಚಾರಣೆಯ ದುಷ್ಟತನದಿಂದ ಮತ್ತು ಬಡತನದ ಪರೀಕ್ಷೆಯಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಸಮಾಧಿ, ನರಕ, ಸಂಪತ್ತು ಮತ್ತು ಬಡತನದ (ದುಆದ ಭಾಗ) ವಿಚಾರಣೆಗಳಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರಿಂದ ಆಶ್ರಯದ ಸಮಗ್ರ ದುಆ."),
        "dua_kufr_faqr" to DuaText("ಅಪನಂಬಿಕೆ ಮತ್ತು ಬಡತನದಿಂದ ನಿರಾಶ್ರಿತರಾದವರು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನಲ್ಲಿ ಅಪನಂಬಿಕೆ ಮತ್ತು ಬಡತನದಿಂದ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ ಮತ್ತು ಸಮಾಧಿಯ ಶಿಕ್ಷೆಯಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ. ನಿನ್ನ ಹೊರತು ಬೇರೆ ದೇವರು ಇಲ್ಲ.", "ಮೂರು ಬಾರಿ ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ (ಸ) ಅವರು ಈ ಮಾತು ಹೇಳುವುದನ್ನು ಅಬು ಬಕ್ರಾ (ರ.) ಕೇಳಿದರು."),
        "dua_sharri_sami" to DuaText("ನನ್ನ ಇಂದ್ರಿಯಗಳ ದುಷ್ಟತನದಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ಶ್ರವಣದ ದುಷ್ಟತನ, ನನ್ನ ದೃಷ್ಟಿಯ ದುಷ್ಟತ್ವ, ನನ್ನ ನಾಲಿಗೆಯ ದುಷ್ಟತ್ವ, ನನ್ನ ಹೃದಯದ ದುಷ್ಟತ್ವ ಮತ್ತು ನನ್ನ ಬಯಕೆಯ ದುಷ್ಟತ್ವಗಳಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಶಕಲ್ ಇಬ್ನ್ ಹುಮಾಯ್ (ರ.) ಗೆ ಕಲಿಸಲಾಯಿತು.", "ಕಾಲುಗಳನ್ನು ಮತ್ತು ತನ್ನನ್ನು ಪಾಪದಿಂದ ರಕ್ಷಿಸಿಕೊಳ್ಳಲು ಒಂದು ದುಆ."),
        "dua_hadm_gharaq" to DuaText("ಹಠಾತ್ ಸಾವು ಮತ್ತು ಅಪಘಾತಗಳಿಂದ ನಿರಾಶ್ರಿತರಾಗುವಿಕೆ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ, (ಕಟ್ಟಡದಿಂದ) ನಜ್ಜುಗುಜ್ಜಾಗುವುದರಿಂದ, ಎತ್ತರದಿಂದ ಬೀಳುವುದರಿಂದ, ಮುಳುಗುವುದರಿಂದ, ಸುಡುವಿಕೆಯಿಂದ ಮತ್ತು ವೃದ್ಧಾಪ್ಯದಿಂದ; ಸಾಯುವ ಸಮಯದಲ್ಲಿ ನನ್ನನ್ನು ದಾರಿ ತಪ್ಪಿಸುವ ಸೈತಾನ್ನಿಂದ, ನಿನ್ನ ಮಾರ್ಗದಿಂದ ಪಲಾಯನ ಮಾಡುವಾಗ ಸಾಯುವುದರಿಂದ ಮತ್ತು (ವಿಷಕಾರಿ) ಕುಟುಕಿನಿಂದ ಸಾಯುವುದರಿಂದ.", "ಅಪಘಾತಗಳು ಮತ್ತು ಕೆಟ್ಟ ಸಾವಿನಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರಿಂದ ಆಶ್ರಯ ಪಡೆದಿರುವ ಒಂದು ದುಆ."),
        "dua_ju_khiyanah" to DuaText("ಹಸಿವು ಮತ್ತು ದ್ರೋಹದಿಂದ ನಿರಾಶ್ರಿತರಾದವರು", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನಲ್ಲಿ ಹಸಿವಿನಿಂದ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ, ಏಕೆಂದರೆ ಅದು ಕೆಟ್ಟ ಸಂಗಾತಿಯಾಗಿದೆ, ಮತ್ತು ನಾನು ನಿನ್ನಲ್ಲಿ ವಿಶ್ವಾಸಘಾತುಕತೆಯಿಂದ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ, ಏಕೆಂದರೆ ಅದು ಕೆಟ್ಟ ವಿಶ್ವಾಸಪಾತ್ರ.", "ಹಸಿವು ಮತ್ತು ದ್ರೋಹದಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರಿಂದ ಆಶ್ರಯ ಪಡೆದಿರುವ ಒಂದು ದುಆ."),
        "dua_huda_tuqa" to DuaText("ಮಾರ್ಗದರ್ಶನ, ಭಕ್ತಿ, ಪವಿತ್ರತೆ ಮತ್ತು ಸಾಕಷ್ಟಿದೆ", "ಓ ಅಲ್ಲಾಹ್ವೇ, ನಾನು ನಿನ್ನನ್ನು ಮಾರ್ಗದರ್ಶನ, ಭಕ್ತಿ, ಪವಿತ್ರತೆ ಮತ್ತು ಸ್ವಾವಲಂಬನೆಗಾಗಿ ಕೇಳಿಕೊಳ್ಳುತ್ತೇನೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರ ಒಂದು ಸಂಕ್ಷಿಪ್ತ, ಸಮಗ್ರವಾದ ದುಆ.", "ಧರ್ಮ ಮತ್ತು ಈ ಪ್ರಪಂಚದ ನಾಲ್ಕು ಮೂಲಭೂತ ಆಶೀರ್ವಾದಗಳು."),
        "dua_aslih_li_dini" to DuaText("ನನ್ನ ಧರ್ಮ, ಜಗತ್ತು ಮತ್ತು ಭವಿಷ್ಯವನ್ನು ಸರಿಪಡಿಸಿ.", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ಎಲ್ಲಾ ವ್ಯವಹಾರಗಳ ರಕ್ಷಣೆಯಾದ ನನ್ನ ಧರ್ಮವನ್ನು ಸರಿಪಡಿಸಿ; ನನ್ನ ಲೌಕಿಕ ಜೀವನವನ್ನು ಸರಿಪಡಿಸಿ, ಅದರಲ್ಲಿ ನನ್ನ ಜೀವನೋಪಾಯವಿದೆ; ಮತ್ತು ನನ್ನ ಪರಲೋಕವನ್ನು ಸರಿಪಡಿಸಿ, ಅದಕ್ಕೆ ನಾನು ಹಿಂತಿರುಗುತ್ತೇನೆ. ನನಗೆ ಜೀವನವನ್ನು ಪ್ರತಿ ಒಳ್ಳೆಯದರಲ್ಲೂ ಹೆಚ್ಚಿಸಿ, ಮತ್ತು ಮರಣವನ್ನು ಪ್ರತಿ ಕೆಟ್ಟದ್ದರಿಂದ ನನಗೆ ಪರಿಹಾರವಾಗಿ ಮಾಡಿ.", "ಧರ್ಮ, ಈ ಜಗತ್ತು ಮತ್ತು ಪರಕಾಲ-ಈ ಮೂರೂ ಸುಧಾರಣೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಸಮಗ್ರ ದುಆ."),
        "dua_musarrifal_qulub" to DuaText("ನಿಮ್ಮ ವಿಧೇಯತೆಗೆ ನಮ್ಮ ಹೃದಯಗಳನ್ನು ತಿರುಗಿಸಿ", "ಓ ಅಲ್ಲಾಹನೇ, ಹೃದಯಗಳನ್ನು ತಿರುಗಿಸುವವನೇ, ನಿನ್ನ ವಿಧೇಯತೆಗೆ ನಮ್ಮ ಹೃದಯಗಳನ್ನು ತಿರುಗಿಸು.", "ಹೃದಯವನ್ನು ವಿಧೇಯತೆಯಲ್ಲಿ ದೃಢವಾಗಿಡಲು ಒಂದು ದುಆ.", "ಎಲ್ಲರ ಹೃದಯಗಳು ಪರಮ ಕರುಣಾಮಯನ ಎರಡು ಬೆರಳುಗಳ ನಡುವೆ ಇರುತ್ತವೆ."),
        "dua_jannah_nar" to DuaText("ಜನ್ನಾವನ್ನು ಬೇಡಿಕೊಳ್ಳುವುದು, ಬೆಂಕಿಯಿಂದ ಆಶ್ರಯ ಪಡೆಯುವುದು", "ಓ ಅಲ್ಲಾಹ್ವೇ, ನಾನು ನಿನ್ನಲ್ಲಿ ಸ್ವರ್ಗವನ್ನು ಬೇಡಿಕೊಳ್ಳುತ್ತೇನೆ ಮತ್ತು ನಾನು ಬೆಂಕಿಯಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ತಾಶಹುದ್ ನಂತರ ಅಥವಾ ಯಾವುದೇ ಸಮಯದಲ್ಲಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಹೇಳಿದರುಃ ನಮ್ಮ ದುಆಗಳು ಸಹ ಇದರ ಸುತ್ತ ಸುತ್ತುತ್ತವೆ."),
        "dua_khayri_kullih" to DuaText("ಈಗ ಮತ್ತು ನಂತರ ಎಲ್ಲವೂ ಚೆನ್ನಾಗಿರುತ್ತದೆ.", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನಲ್ಲಿ ಎಲ್ಲಾ ಒಳ್ಳೆಯದಕ್ಕೂ-ತಕ್ಷಣದ ಮತ್ತು ವಿಳಂಬವಾದದ್ದಕ್ಕೂ-ನನಗೆ ತಿಳಿದಿರುವ ಮತ್ತು ನನಗೆ ತಿಳಿಯದ ಎಲ್ಲಾ ವಿಷಯಗಳಿಗೂ-- ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ-ತಕ್ಷಣದ ಮತ್ತು ವಿಳಂಬವಾದ, ನನಗೆ ತಿಳಿದಿರುವ ಮತ್ತು ನನಗೆ ತಿಳಿಯದ ಎಲ್ಲಾ ಕೆಟ್ಟ ಸಂಗತಿಗಳಿಂದ-- ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನಲ್ಲಿ ಸ್ವರ್ಗವನ್ನು ಬೇಡಿಕೊಳ್ಳುತ್ತೇನೆ ಮತ್ತು ಯಾವುದೇ ಮಾತುಗಳು ಮತ್ತು ಕಾರ್ಯಗಳು ನನ್ನನ್ನು ಅದರ ಹತ್ತಿರಕ್ಕೆ ತರುತ್ತವೆ, ಮತ್ತು ನಾನು ಬೆಂಕಿಯಿಂದ ಮತ್ತು ಯಾವುದೇ ಮಾತುಗಳು ಮತ್ತು ಕಾರ್ಯಗಳಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಆಯೆಷಾ (ರಾ) ಅವರಿಗೆ (ದುಆದ ಭಾಗ) ಈ ಸಮಗ್ರ ದುಆವನ್ನು ಕಲಿಸಿದರು.", "ಪ್ರತಿಯೊಂದು ಒಳ್ಳೆಯದನ್ನು ಸಂಗ್ರಹಿಸುವ ಒಂದು ದುಆ."),
        "dua_ihdini_saddidni" to DuaText("ನನಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಿ ಮತ್ತು ನನ್ನನ್ನು ನಿಖರವಾಗಿ ಇರಿಸಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನನಗೆ ಮಾರ್ಗದರ್ಶನ ಮಾಡು ಮತ್ತು ನನ್ನನ್ನು ಸರಿಯಾದ ಹಾದಿಯಲ್ಲಿ ಸಾಗಿಸು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಇದನ್ನು ಅಲಿ (ರ.) ಅವರಿಗೆ ಕಲಿಸಿದರು.", "ಮಾರ್ಗದರ್ಶನವನ್ನು ರಸ್ತೆಯ ಉದ್ದಕ್ಕೂ ಮಾರ್ಗದರ್ಶನ ಎಂದು ಭಾವಿಸಿ, ಮತ್ತು ಸದಾದ್ ಅನ್ನು ಬಾಣದ ನೇರತೆ ಎಂದು ಭಾವಿಸಿ."),
        "dua_hubbaka" to DuaText("ಅಲ್ಲಾಹನ ಪ್ರೀತಿಯನ್ನು ಬೇಡಿಕೊಳ್ಳುವುದು.", "ಓ ಅಲ್ಲಾಹನೇ, ನಿನ್ನ ಪ್ರೀತಿಯನ್ನು, ನಿನ್ನನ್ನು ಪ್ರೀತಿಸುವವರ ಪ್ರೀತಿಯನ್ನು ಮತ್ತು ನಿನ್ನ ಪ್ರೀತಿಯನ್ನು ನನಗೂ ತಲುಪಿಸುವ ಕ್ರಿಯೆಗಳನ್ನು ನಾನು ನಿನ್ನನ್ನು ಕೋರುತ್ತೇನೆ. ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ಪ್ರೀತಿ, ನನ್ನ ಕುಟುಂಬ ಮತ್ತು ತಂಪಾದ ನೀರಿಗಿಂತ ನಿನ್ನ ಪ್ರೀತಿಯನ್ನು ನನಗೆ ಹೆಚ್ಚು ಪ್ರಿಯವಾಗಿಸು.", "ದಾವೂದ್ (ಅ. ಸ.) ನ ದುಆ ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರಿಂದ ಸಂಬಂಧಿಸಿದೆ.", "ಅಲ್ಲಾಹುವಿನ ಪ್ರೀತಿಯೇ ಅತ್ಯಂತ ದೊಡ್ಡ ಸಂಪತ್ತು."),
        "dua_filal_khayrat" to DuaText("ಒಳ್ಳೆಯದನ್ನು ಮಾಡುವುದು ಮತ್ತು ಕೆಟ್ಟದ್ದನ್ನು ಬಿಟ್ಟುಬಿಡುವುದು", "ಓ ಅಲ್ಲಾಹನೇ, ಒಳ್ಳೆಯ ಕಾರ್ಯಗಳನ್ನು ಮಾಡಲು, ಕೆಟ್ಟ ಕಾರ್ಯಗಳನ್ನು ಬಿಟ್ಟುಹೋಗಲು ಮತ್ತು ಬಡವರನ್ನು ಪ್ರೀತಿಸಲು ನನಗೆ ಅವಕಾಶ ಮಾಡಿಕೊಡಿ ಮತ್ತು ನೀನು ನನ್ನನ್ನು ಕ್ಷಮಿಸು ಮತ್ತು ನನ್ನ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸು ಎಂದು ನಾನು ನಿನ್ನನ್ನು ಕೇಳಿಕೊಳ್ಳುತ್ತೇನೆ. ಮತ್ತು ನೀವು ಒಂದು ಜನಾಂಗಕ್ಕೆ ವಿಚಾರಣೆ ನಡೆಸಲು ಉದ್ದೇಶಿಸಿದಾಗ, ನನ್ನನ್ನು ವಿಚಾರಣೆಗೆ ಒಳಪಡಿಸದಂತೆ ನನ್ನನ್ನು ಕರೆದೊಯ್ಯಿರಿ. ನಾನು ನಿನ್ನ ಪ್ರೀತಿಯನ್ನು, ನಿನ್ನನ್ನು ಪ್ರೀತಿಸುವವರ ಪ್ರೀತಿಯನ್ನು ಮತ್ತು ನಿನ್ನ ಪ್ರೀತಿಯನ್ನು ಹತ್ತಿರ ತರುವ ಕಾರ್ಯಗಳ ಪ್ರೀತಿಯನ್ನು ಕೇಳುತ್ತೇನೆ.", "ಅಲ್ಲಾಹ್ ಈ ದುಆವನ್ನು ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರಿಗೆ ಕನಸಿನಲ್ಲಿ ಕಲಿಸಿದನು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಹೇಳಿದರುಃ ಇದು ನಿಜ, ಆದ್ದರಿಂದ ಅದನ್ನು ಕಲಿಯಿರಿ ಮತ್ತು ಕಲಿಸಿ."),
        "dua_bi_ilmikal_ghayb" to DuaText("ಜೀವನವು ಒಳ್ಳೆಯದಾಗಿರುತ್ತದೆಯಾದರೂ ನನ್ನನ್ನು ಬದುಕಲು ಬಿಡಿ.", "ಓ ಅಲ್ಲಾಹನೇ, ಕಾಣದ ಸಂಗತಿಗಳ ಬಗೆಗಿನ ನಿನ್ನ ಜ್ಞಾನ ಮತ್ತು ಸೃಷ್ಟಿಯ ಮೇಲಿನ ನಿನ್ನ ಶಕ್ತಿಯಿಂದ-ನನಗೆ ಜೀವನವು ಉತ್ತಮವೆಂದು ನಿನಗೆ ತಿಳಿದಿರುವವರೆಗೆ ನನ್ನನ್ನು ಜೀವಂತವಾಗಿರಿಸು. ಮತ್ತು ನನಗೆ ಮರಣವು ಉತ್ತಮವೆಂದು ನಿನಗೆ ತಿಳಿದಿರುವಾಗ ನನ್ನನ್ನು ಕರೆದೊಯ್. ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನನ್ನು ಏಕಾಂತದಲ್ಲಿ ಮತ್ತು ಸಾರ್ವಜನಿಕವಾಗಿ, ಸಮಾಧಾನದಲ್ಲಿ ಮತ್ತು ಕೋಪದಲ್ಲಿ ಸತ್ಯದ ಮಾತಾಗಿ, ಮತ್ತು ಬಡತನದಲ್ಲಿ ಮತ್ತು ಸಂಪತ್ತಿನಲ್ಲಿ ಮಿತವಾಗಲು ಕೇಳಿಕೊಳ್ಳುತ್ತೇನೆ.", "ಅಮ್ಮರ್ ಇಬ್ನ್ ಯಾಸಿರ್ (ಆರ್. ಎ.) (ಆರಂಭಿಕ ಭಾಗ) ಅವರ ಪ್ರಾರ್ಥನೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಪ್ರಾರ್ಥನೆಯಲ್ಲಿ ಈ ದುಆವನ್ನು ಮಾಡಿದರು."),
        "dua_ism_azam_mannan" to DuaText("ಇಸ್ಮ್-ಎ-ಅಜಮ್-ಅಲ್-ಮನ್ನಾನ್", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನನ್ನು ಬೇಡಿಕೊಳ್ಳುತ್ತೇನೆ, ಏಕೆಂದರೆ ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ನಿನಗೆ ಸೇರಿದ್ದು. ನಿನ್ನ ಹೊರತು ಬೇರೆ ದೇವರು ಇಲ್ಲ, ಅನುಗ್ರಹವನ್ನು ನೀಡುವವನು, ಆಕಾಶಗಳ ಮತ್ತು ಭೂಮಿಯ ಸೃಷ್ಟಿಕರ್ತ. ಓ ಘನತೆ ಮತ್ತು ಗೌರವದ ಒಡೆಯನೇ, ಓ ಶಾಶ್ವತ ಜೀವಿಯೇ, ಓ ಪೋಷಕೇ!", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರು ಈ ವ್ಯಕ್ತಿಯು ಅಲ್ಲಾಹ್ನ ಶ್ರೇಷ್ಠ ಹೆಸರಿನಿಂದ ದುಆವನ್ನು ಮಾಡಿದನು ಎಂದು ಹೇಳಿದರು.", "ಈ ಹೆಸರಿನಿಂದ ಮಾಡಿದ ದುಆಕ್ಕೆ ಉತ್ತರಿಸಲಾಗುತ್ತದೆ."),
        "dua_ism_azam_ahad_samad" to DuaText("ಇಸ್ಮ್-ಎ-ಅಜಮ್-ಅಲ್-ಅಹದ್ ಅಸ್-ಸಮದ್", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನ್ನನ್ನು ಕೇಳಿಕೊಳ್ಳುತ್ತೇನೆ, ಏಕೆಂದರೆ ನಾನು ಅಲ್ಲಾಹನೆಂದು ಸಾಕ್ಷಿಯಾಗಿ ಹೇಳುತ್ತೇನೆ; ನಿನ್ನನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆ ಯಾವುದೇ ದೇವರು ಇಲ್ಲ, ಒಬ್ಬನೇ, ಸ್ವಾವಲಂಬಿಯಾದ, ಹುಟ್ಟುವುದಿಲ್ಲ ಅಥವಾ ಹುಟ್ಟುವುದಿಲ್ಲ, ಮತ್ತು ಅವನಿಗೆ ಹೋಲಿಸಬಹುದಾದವರು ಯಾರೂ ಇಲ್ಲ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಈ ವ್ಯಕ್ತಿಯು ಅಲ್ಲಾಹನನ್ನು ಆತನ ಶ್ರೇಷ್ಠ ಹೆಸರಿನಿಂದ ಕೇಳಿದ್ದಾಗಿ ಹೇಳಿದರು.", "ಅದರ ಮೂಲಕ ಕೇಳಿದಾಗ, ಅವನು ಕೊಡುತ್ತಾನೆ; ಅದರ ಮೂಲಕ ಕರೆದಾಗ, ಅವನು ಉತ್ತರಿಸುತ್ತಾನೆ."),
        "dua_thabbitni_hadiyan" to DuaText("ನನ್ನನ್ನು ದೃಢ, ಮಾರ್ಗದರ್ಶಿತ ಮತ್ತು ಮಾರ್ಗದರ್ಶಿಯಾಗಿ ಮಾಡಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನನ್ನು ದೃಢವಾಗಿಸು ಮತ್ತು ನನಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡುವ ಮತ್ತು ಮಾರ್ಗದರ್ಶನ ನೀಡುವವನಾಗಿಸು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಈ ದುಆವನ್ನು ಜರೀರ್ (ರಾ) (ನಿಮಗಾಗಿ'ಥಾಬಿತ್ನಿ'ಎಂದು ಹೇಳಿಕೊಳ್ಳಿ) ಗಾಗಿ ಮಾಡಿದರು.", "ಜರೀರ್ (ಆರ್. ಎ.) ನ ಮೂಲ ದುಆ'ಥಾಬಿಟ್-ಹು'ಪದಗಳನ್ನು ಬಳಸುತ್ತದೆ."),
        "dua_rabbighfir_tub_alayya" to DuaText("ನನ್ನನ್ನು ಕ್ಷಮಿಸಿ ಮತ್ತು ನನ್ನ ಪಶ್ಚಾತ್ತಾಪವನ್ನು ಸ್ವೀಕರಿಸಿ.", "ನನ್ನ ಒಡೆಯನೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸು ಮತ್ತು ನನ್ನ ಪಶ್ಚಾತ್ತಾಪವನ್ನು ಸ್ವೀಕರಿಸು. ನಿಶ್ಚಯವಾಗಿ ನೀನು ಪಶ್ಚಾತ್ತಾಪಪಡುವವನು, ಕರುಣಾಮಯಿ.", "ಒಂದೇ ಸಭೆಯಲ್ಲಿ ನೂರು ಬಾರಿ-ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರ ಅಭ್ಯಾಸ.", "ಸಹಚರರು ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಒಂದೇ ಸಭೆಯಲ್ಲಿ ನೂರು ಬಾರಿ ಇದನ್ನು ಹೇಳಿದ್ದನ್ನು ಎಣಿಸಿದರು."),
        "dua_rafiq_ala" to DuaText("ಸಾಯುತ್ತಿರುವ ವ್ಯಕ್ತಿಯ ದುಆ", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನನ್ನು ಕ್ಷಮಿಸು, ನನ್ನ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸು ಮತ್ತು ಅತ್ಯುನ್ನತ ಸಂಗಾತಿಯೊಂದಿಗೆ ನನ್ನೊಂದಿಗೆ ಸೇರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ನ ಕೊನೆಯ ದುಆ-ಅನಾರೋಗ್ಯದ ವ್ಯಕ್ತಿಗೆ ಸ್ವತಃ ಹೇಳಲು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ನಿಧನರಾದ ಸಮಯದಲ್ಲಿ ಈ ದುಆ ಮಾಡಿದರು."),
        "dua_la_bas_tahur" to DuaText("ರೋಗಿಗೆ ಸಾಂತ್ವನ ನೀಡುವುದುಃ ಶುದ್ಧೀಕರಣ", "ಯಾವುದೇ ಹಾನಿ ಇಲ್ಲ; ಅಲ್ಲಾಹನು ಬಯಸಿದರೆ ಅದು (ಪಾಪಗಳಿಂದ) ಶುದ್ಧೀಕರಣವಾಗಿದೆ.", "ಭೇಟಿ ನೀಡಿದಾಗ ರೋಗಿಗಳಿಗೆ ಸಾಂತ್ವನ ನೀಡುವುದು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ರೋಗಿಗಳನ್ನು ಭೇಟಿ ಮಾಡುವಾಗ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_talqeen" to DuaText("ಸಾವಿನ ಬಗ್ಗೆ ತಲ್ಕೀನ್", "ಅಲ್ಲಾಹನನ್ನು ಹೊರತುಪಡಿಸಿ ಬೇರೆ ಯಾರಿಗೂ ಆರಾಧನೆ ಮಾಡುವ ಹಕ್ಕಿಲ್ಲ.", "ಸಾಯುತ್ತಿರುವ ವ್ಯಕ್ತಿಯ ಬಳಿ ಕಲಿಮಾ ಪಠಿಸಿ (ಅದನ್ನು ಹೇಳಲು ಅವರನ್ನು ಒತ್ತಾಯಿಸಬೇಡಿ).", "'ಲಾ ಇಲಾಹಾ ಇಲ್ಲಲ್ಲಾ'ಎಂಬ ಕೊನೆಯ ಮಾತುಗಳು ಯಾರಿಗಾದರೂ ಸ್ವರ್ಗವನ್ನು ಪ್ರವೇಶಿಸುತ್ತವೆ (ಅಬು ದಾವೂದ್ 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("ಸಾವಿನ ಆಸೆಯ ಬದಲು", "ಓ ಅಲ್ಲಾಹನೇ, ನನಗೆ ಜೀವನವು ಉತ್ತಮವಾಗಿರುವವರೆಗೆ ನನ್ನನ್ನು ಜೀವಂತವಾಗಿರಿಸು, ಮತ್ತು ನನಗೆ ಮರಣವು ಉತ್ತಮವಾದಾಗ ನನ್ನನ್ನು ಕರೆದೊಯ್ಯು.", "ಕಷ್ಟದಲ್ಲಿ ಸಾಯಲು ಬಯಸುವುದರ ಬದಲು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರು ಮರಣವನ್ನು ಬಯಸುವುದನ್ನು ನಿಷೇಧಿಸಿದರು ಮತ್ತು ಬದಲಿಗೆ ಇದನ್ನು ಕಲಿಸಿದರು."),
        "dua_for_one_i_cursed" to DuaText("ನಾನು ಪದಗಳಿಂದ ನೋಯಿಸುವ ಯಾರಿಗಾದರೂ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಯಾರನ್ನು ಅವಮಾನಿಸಿದ್ದೇನೆಯೋ ಆ ಯಾವುದೇ ನಂಬಿಕೆಯುಳ್ಳವನು ಅದನ್ನು ಪುನರುತ್ಥಾನದ ದಿನದಂದು ನಿನಗೆ ಹತ್ತಿರವಾಗುವ ಸಾಧನವನ್ನಾಗಿ ಮಾಡಿಕೊಳ್ಳಿ.", "ನೀವು ಕೋಪದಲ್ಲಿ ಕೆಟ್ಟದಾಗಿ ಮಾತನಾಡುವ ಯಾರಿಗಾದರೂ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಒಂದು ದುಆ."),
        "dua_praising_someone" to DuaText("ಯಾರನ್ನಾದರೂ ಸ್ತುತಿಸುವಾಗ", "ನಾನು ಹೀಗೆಂದು ಪರಿಗಣಿಸುತ್ತೇನೆ, ಮತ್ತು ಅಲ್ಲಾಹ್ ಅವನ ಲೆಕ್ಕಗಾರನಾಗಿದ್ದಾನೆ, ಮತ್ತು ನಾನು ಅಲ್ಲಾಹನ ಮುಂದೆ ಯಾರ ಪರಿಶುದ್ಧತೆಯನ್ನೂ ದೃಢೀಕರಿಸುವುದಿಲ್ಲ.", "ಯಾರನ್ನಾದರೂ ಹೊಗಳುವಾಗ, ಉತ್ಪ್ರೇಕ್ಷೆ ಮಾಡುವ ಬದಲು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಈ ಸ್ತುತಿಯ ಶಿಷ್ಟಾಚಾರವನ್ನು ಕಲಿಸಿದರು."),
        "dua_being_praised" to DuaText("ನೀವು ಸ್ತುತಿಸಲ್ಪಡುವಾಗ", "ಓ ಅಲ್ಲಾಹನೇ, ಅವರು ಏನು ಹೇಳುತ್ತಾರೆಂಬುದಕ್ಕೆ ನನ್ನನ್ನು ಲೆಕ್ಕಕ್ಕೆ ತೆಗೆದುಕೊಳ್ಳಬೇಡ, ಮತ್ತು ಅವರಿಗೆ ತಿಳಿಯದ ವಿಷಯಗಳಿಗೆ ನನ್ನನ್ನು ಕ್ಷಮಿಸು.", "ತನ್ನನ್ನು ತಾನು ಹೊಗಳಿಕೊಳ್ಳುವುದನ್ನು ಕೇಳಿದಾಗ-ಸಹಚರ (ಆರ್. ಎ.) ಅಭ್ಯಾಸ.", "ಹೊಗಳಿದಾಗ ಅಹಂಕಾರವನ್ನು ತಪ್ಪಿಸುವ ಒಂದು ಮಾರ್ಗ."),
        "dua_non_muslim_sneezes" to DuaText("ಮುಸ್ಲಿಮೇತರರು ಸೀನುವಾಗ", "ಅಲ್ಲಾಹ್ ನಿಮಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡಲಿ ಮತ್ತು ನಿಮ್ಮ ವ್ಯವಹಾರಗಳನ್ನು ಸರಿಪಡಿಸಿ.", "ಮುಸ್ಲಿಮೇತರರು ಸೀನಿ'ಅಲ್ಹಮ್ದುಲಿಲ್ಲಾಹ್'ಎಂದು ಹೇಳಿದಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು'ಯಾರ್ಹಮುಕಲ್ಲಾ'ಎಂದು ಹೇಳುತ್ತಾರೆ ಎಂಬ ನಿರೀಕ್ಷೆಯಲ್ಲಿ ಯಹೂದಿಗಳು ಅವರ ಬಳಿ ಸೀನಿದರು ಮತ್ತು ಅವರು ಇದನ್ನು ಹೇಳುತ್ತಿದ್ದರು."),
        "dua_reply_ahl_kitab_salam" to DuaText("ಪುಸ್ತಕದ ಜನರ ನಮಸ್ಕಾರಕ್ಕೆ ಉತ್ತರಿಸುವುದು", "ಮತ್ತು ನಿಮ್ಮ ಮೇಲೆ.", "ಯಾವಾಗ ಗ್ರಂಥದ ಜನರು ಸಲಾಂನೊಂದಿಗೆ ಸ್ವಾಗತಿಸುತ್ತಾರೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರ ಸೂಚನೆಗಳು."),
        "dua_fasting_invited" to DuaText("ಉಪವಾಸ ಮಾಡುವಾಗ ಆಹ್ವಾನಿಸಿದಾಗ", "ನಾನು ಉಪವಾಸ ಮಾಡುತ್ತಿದ್ದೇನೆ.", "ಉಪವಾಸ ಮಾಡುವಾಗ ಆಹ್ವಾನಿಸಿದಾಗ, ಅಥವಾ ಯಾರಾದರೂ ನಿಮ್ಮೊಂದಿಗೆ ಜಗಳವಾಡುವಾಗ.", "ಉಪವಾಸ ಮಾಡುವ ವ್ಯಕ್ತಿಯು ಆಹ್ವಾನವನ್ನು ಸ್ವೀಕರಿಸಿದರೆ, ಆತ ಆತಿಥೇಯರಿಗಾಗಿ ಪ್ರಾರ್ಥಿಸಬೇಕು."),
        "dua_for_who_gave_drink" to DuaText("ನನಗೆ ಆಹಾರ ನೀಡಿದವರಿಗಾಗಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನನಗೆ ಆಹಾರ ನೀಡಿದವನಿಗೆ ಆಹಾರ ಕೊಡು ಮತ್ತು ನನಗೆ ಪಾನೀಯವನ್ನು ನೀಡಿದವನಿಗೆ ಪಾನೀಯವನ್ನು ಕೊಡು.", "ನಿಮಗೆ ಆಹಾರ ಅಥವಾ ಪಾನೀಯವನ್ನು ನೀಡುವವರಿಗಾಗಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಅಲ್-ಮಿಕ್ದಾದ್ (ರ. ಅ.) ಗಾಗಿ ಈ ದುಆವನ್ನು ಮಾಡಿದರು."),
        "dua_eid_greeting" to DuaText("ಈದ್ ಶುಭಾಶಯಗಳು", "ಅಲ್ಲಾಹನು ನಮ್ಮಿಂದ ಮತ್ತು ನಿಮ್ಮಿಂದ (ಒಳ್ಳೆಯ ಕಾರ್ಯಗಳನ್ನು) ಸ್ವೀಕರಿಸಲಿ.", "ಈದ್ ದಿನದಂದು ಒಬ್ಬರಿಗೊಬ್ಬರು-ಉದಾತ್ತ ಸಹಚರರ (ಆರ್. ಎ.) ಅಭ್ಯಾಸ.", "ಈದ್ ದಿನದಂದು ಭೇಟಿಯಾದಾಗ ಸಹಚರರು ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_wedding_night" to DuaText("ನಿಕಾಹ್ನ ನಂತರ ವಧುವಿಗೆ", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ಅವಳನ್ನು ಸೃಷ್ಟಿಸಿದ ಪ್ರಕೃತಿಯ ಒಳಿತಿಗಾಗಿ ಮತ್ತು ಒಳ್ಳೆಯದಕ್ಕಾಗಿ ನಾನು ನಿನ್ನನ್ನು ಕೇಳುತ್ತೇನೆ, ಮತ್ತು ಅವಳ ದುಷ್ಟತನದಿಂದ ಮತ್ತು ನೀನು ಅವಳನ್ನು ಸೃಷ್ಟಿಸಿದ ಪ್ರಕೃತಿಯ ಕೆಟ್ಟತನದಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ವಿವಾಹದ ನಂತರ, ಹೆಂಡತಿಯ ಹಣೆಯ ಮೇಲೆ ಕೈ ಇರಿಸಿ.", "ಪ್ರವಾದಿಯ ಸಲ್ಲು ಅಲ್ಲಾಹ್ ವಸ್ ಲಾಮ್ ಬೋಧನೆ-ಮದುವೆಯಲ್ಲಿ ಆಶೀರ್ವಾದ."),
        "dua_istisqa_ibadak" to DuaText("ನಿಮ್ಮ ಸೇವಕರಿಗೆ ಮತ್ತು ಪ್ರಾಣಿಗಳಿಗೆ ನೀರುಣಿಸಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನಿನ್ನ ಸೇವಕರಿಗೆ ಮತ್ತು ನಿನ್ನ ಪ್ರಾಣಿಗಳಿಗೆ ನೀರು ಕೊಡು, ನಿನ್ನ ಕರುಣೆಯನ್ನು ಹರಡಿ ಮತ್ತು ನಿನ್ನ ಮೃತ ಭೂಮಿಗೆ ಜೀವವನ್ನು ಕೊಡು.", "ಮಳೆಗಾಗಿ ಕೇಳುವುದು (ಇಸ್ತಿಸ್ಕಾ).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಮಳೆಗಾಗಿ ಈ ದುಆವನ್ನು ಮಾಡಿದರು."),
        "dua_seeing_clouds" to DuaText("ಕತ್ತಲ ಮೋಡಗಳನ್ನು ನೋಡುವುದು", "ಓ ಅಲ್ಲಾಹನೇ, ಅದರ ದುಷ್ಟತನದಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಆಕಾಶದಲ್ಲಿ ಕಪ್ಪು ಮೋಡಗಳನ್ನು ನೋಡಿದಾಗ; ಮಳೆ ಬಂದರೆ,'ಅಲ್ಲಾಹುಮ್ಮಾ ಸೈಯ್ಯಿಬನ್ ನಫಿಯಾ'ಎಂದು ಹೇಳಿ.", "ಮೋಡಗಳನ್ನು ನೋಡಿದ ನಂತರ, ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಏನು ಮಾಡುತ್ತಿದ್ದರು ಎಂಬುದನ್ನು ಬಿಟ್ಟು ಈ ದುಆ ಮಾಡುತ್ತಾರೆ."),
        "dua_jamarat" to DuaText("ಜಮಾರಾಟ್ಗೆ ಕಲ್ಲು ತೂರಾಟ", "ಅಲ್ಲಾಹು ಶ್ರೇಷ್ಠನು.", "ಪ್ರತಿ ಕಲ್ಲಿನೊಂದಿಗೆ ಎಸೆಯಲಾಗುತ್ತದೆ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಪ್ರತಿ ಕಲ್ಲಿನೊಂದಿಗೆ ತಕ್ಬೀರ್ ಅನ್ನು ಹೇಳಿದರು, ನಂತರ ಮೊದಲ ಮತ್ತು ಎರಡನೇ ಜಮ್ರಾ ನಂತರ ಕಿಬ್ಲಾವನ್ನು ಎದುರಿಸಿ ದೀರ್ಘವಾದ ದುಆ ಮಾಡಿದರು."),
        "dua_rabbi_ainni" to DuaText("ನನ್ನ ಒಡೆಯನೇ, ನನಗೆ ಸಹಾಯ ಮಾಡು, ನನ್ನ ವಿರುದ್ಧವಲ್ಲ.", "ನನ್ನ ಒಡೆಯನೇ, ನನಗೆ ಸಹಾಯ ಮಾಡು ಮತ್ತು ನನ್ನ ವಿರುದ್ಧ ಬೇರೆಯವರಿಗೆ ಸಹಾಯ ಮಾಡು, ನನಗೆ ವಿಜಯವನ್ನು ಮಾಡು ಮತ್ತು ನನ್ನ ಮೇಲೆ ಬೇರೆಯವರಿಗೆ ವಿಜಯವನ್ನು ಮಾಡು, ನನಗಾಗಿ ಯೋಜಿಸು ಮತ್ತು ನನ್ನ ವಿರುದ್ಧ ಯೋಜಿಸಬೇಡ, ನನಗೆ ಮಾರ್ಗದರ್ಶನ ಮಾಡು ಮತ್ತು ನನಗೆ ಮಾರ್ಗದರ್ಶನವನ್ನು ಸುಲಭಗೊಳಿಸು, ಮತ್ತು ನನಗೆ ಅನ್ಯಾಯ ಮಾಡುವವರ ವಿರುದ್ಧ ನನಗೆ ಸಹಾಯ ಮಾಡು.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ (ಆರಂಭಿಕ ಭಾಗ) ಅವರ ಸಮಗ್ರ ದುಆ.", "ಧರ್ಮ ಮತ್ತು ಈ ಜಗತ್ತಿನಲ್ಲಿ ಎಲ್ಲ ಸಹಾಯವನ್ನು ಸಂಗ್ರಹಿಸುವ ದುಆ."),
        "dua_ati_nafsi_taqwaha" to DuaText("ನನ್ನ ಆತ್ಮಕ್ಕೆ ಅದರ ತಕ್ವಾ ಕೊಡಿ.", "ಓ ಅಲ್ಲಾಹನೇ, ನನ್ನ ಆತ್ಮಕ್ಕೆ ಅದರ ಭಕ್ತಿಯನ್ನು ಕೊಡು ಮತ್ತು ಅದನ್ನು ಶುದ್ಧೀಕರಿಸು. ಏಕೆಂದರೆ ಅದನ್ನು ಶುದ್ಧೀಕರಿಸುವವನು ನೀನು. ನೀನು ಅದರ ರಕ್ಷಕನೂ, ಒಡೆಯನೂ ಆಗಿದ್ದೀ.", "ಸ್ವಯಂ ಸುಧಾರಣೆ ಮತ್ತು ಶುದ್ಧೀಕರಣಕ್ಕಾಗಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಈ ದುಆವನ್ನು ತಯಾರಿಸುತ್ತಿದ್ದರು."),
        "dua_iqsim_lana_khashyatik" to DuaText("ನಿಮ್ಮ ಬಗ್ಗೆ ನಮಗೆ ಅಂತಹ ಭಯವನ್ನು ದಯಪಾಲಿಸಿ.", "ಓ ಅಲ್ಲಾಹನೇ, ನಮಗೆ ನಿಮ್ಮ ಬಗ್ಗೆ ಸಾಕಷ್ಟು ಭಯವಿರಲಿ, ನಿಮ್ಮ ಸ್ವರ್ಗಕ್ಕೆ ನಮ್ಮನ್ನು ಕರೆತರುವಷ್ಟು ನಿಮ್ಮ ವಿಧೇಯತೆಯನ್ನು ಮತ್ತು ಈ ಜಗತ್ತಿನ ವಿಪತ್ತುಗಳನ್ನು ನಮಗೆ ಸುಲಭಗೊಳಿಸುವಷ್ಟು ಖಚಿತತೆಯನ್ನು ನಮಗೆ ನೀಡಲಿ. ನೀವು ನಮ್ಮನ್ನು ಜೀವಂತವಾಗಿಡುವವರೆಗೆ ನಾವು ನಮ್ಮ ಶ್ರವಣಶಕ್ತಿಯನ್ನು, ನಮ್ಮ ದೃಷ್ಟಿಯನ್ನು ಮತ್ತು ನಮ್ಮ ಶಕ್ತಿಯನ್ನು ಆನಂದಿಸೋಣ. ಮತ್ತು ಅವುಗಳನ್ನು ಶಾಶ್ವತಗೊಳಿಸೋಣ. ನಮಗೆ ಅನ್ಯಾಯ ಮಾಡಿದವರ ಮೇಲೆ ನಾವು ಸೇಡು ತೀರಿಸಿಕೊಳ್ಳೋಣ, ನಮ್ಮ ಶತ್ರುಗಳ ವಿರುದ್ಧ ನಮಗೆ ಸಹಾಯ ಮಾಡಿ, ನಮ್ಮ ಸಂಕಟವು ನಮ್ಮ ಧರ್ಮದಲ್ಲಿರಲು ಬಿಡಬೇಡಿ, ಈ ಜಗತ್ತನ್ನು ನಮ್ಮ ಅತಿದೊಡ್ಡ ಕಾಳಜಿಯಾಗಲೀ ಅಥವಾ ನಮ್ಮ ಜ್ಞಾನದ ಮಿತಿಯಾಗಲೀ ಮಾಡಬೇಡಿ, ಮತ್ತು ನಮಗೆ ಯಾವುದೇ ಕರುಣೆ ತೋರಿಸದವರನ್ನು ನಮ್ಮ ಮೇಲೆ ಹಾಕಬೇಡಿ.", "ಒಂದು ಕೂಟದಿಂದ ಎದ್ದಾಗ-ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಈ ದುಆ ಮಾಡದೆ ಏಳುವುದು ಅಪರೂಪ.", "ಧರ್ಮ, ಈ ಜಗತ್ತು ಮತ್ತು ಪರಕಾಲದ ಒಳಿತಿಗಾಗಿ ಸಮಗ್ರವಾದ ದುಆ."),
        "dua_infani_bima_allamtani" to DuaText("ನೀವು ನನಗೆ ಕಲಿಸಿದ ವಿಷಯಗಳಿಂದ ನನಗೆ ಪ್ರಯೋಜನವನ್ನು ನೀಡಿ.", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ನನಗೆ ಕಲಿಸಿದವುಗಳಿಂದ ನನಗೆ ಪ್ರಯೋಜನವಾಗಲಿ, ನನಗೆ ಪ್ರಯೋಜನವಾಗುವುದು ಏನು ಎಂದು ನನಗೆ ಕಲಿಸು ಮತ್ತು ನನಗೆ ಜ್ಞಾನವನ್ನು ಹೆಚ್ಚಿಸು.", "ಜ್ಞಾನವನ್ನು ಹುಡುಕುವಾಗ ಅಥವಾ ಅಧ್ಯಯನ ಮಾಡುವ ಮೊದಲು.", "ಪ್ರಯೋಜನಕಾರಿ ಜ್ಞಾನ ಮತ್ತು ಅದರ ಮೇಲೆ ಕಾರ್ಯನಿರ್ವಹಿಸಲು ಒಂದು ದುಆ."),
    )
}
